"""Synthetic training curves generated by the physics chain."""

from __future__ import annotations

import numpy as np
import pandas as pd
from scipy.stats import qmc

from jominy.materials import ELEMENTS, Composition
from jominy.physics import PhysicsModel

#: Sampling box (wt%). It encloses every composition of the real data (heats and band
#: corners) and stays inside the low-alloy domain of the Creusot-Loire equations.
SAMPLING_BOX: dict[str, tuple[float, float]] = {
    "C": (0.12, 0.60),
    "Si": (0.0, 0.45),
    "Mn": (0.40, 1.50),
    "P": (0.0, 0.035),
    "Cr": (0.0, 1.90),
    "Ni": (0.0, 1.90),
    "Mo": (0.0, 0.40),
    "V": (0.0, 0.10),
    "Cu": (0.0, 0.40),
}

STANDARD_DISTANCES = np.array([1.5, 3, 5, 7, 9, 11, 13, 15, 20, 25, 30, 35, 40, 45, 50])


def sample_compositions(n: int, seed: int) -> list[Composition]:
    """Latin-hypercube sample of ``n`` compositions inside :data:`SAMPLING_BOX`."""
    unit = qmc.LatinHypercube(d=len(ELEMENTS), seed=seed).random(n)
    lo = np.array([SAMPLING_BOX[e][0] for e in ELEMENTS])
    hi = np.array([SAMPLING_BOX[e][1] for e in ELEMENTS])
    values = lo + unit * (hi - lo)
    return [Composition(**dict(zip(ELEMENTS, row, strict=True))) for row in values]


def synthetic_frame(n: int, seed: int, physics: PhysicsModel) -> pd.DataFrame:
    """Long-format table of ``n`` simulated curves at the standard distances."""
    rows = []
    for i, comp in enumerate(sample_compositions(n, seed)):
        hrc = physics.predict_curve(comp, STANDARD_DISTANCES)
        for d, h in zip(STANDARD_DISTANCES, hrc, strict=True):
            rows.append(
                {
                    "curve_id": f"syn{i:05d}",
                    **comp.as_dict(),
                    "distance_mm": float(d),
                    "hrc": float(h),
                }
            )
    return pd.DataFrame(rows)
